import {organizationsForCity} from './personalization.js';
import {FEED,COURSES,CATEGORIES,ORGANIZATIONS,visibleFeed,calendarDays} from './community-data.js';
import {PSALM23} from './psalms.js';
import {EVIDENCE,ACTION_EVIDENCE} from './community-copy.js';
import {escapeHTML as esc} from './core.js';
export function createCommunity({t,ico,prefs,getEdition,getMood,getProfile,navigate,render,toast,modal,closeModal,download,focusMain}){
 const now=new Date(),s={filter:'all',query:'',item:null,course:null,category:'all',lesson:0,month:now.getMonth(),year:now.getFullYear(),day:now.getDate(),liked:[],likes:{},counts:{},comments:[],commentsLoading:false,commentsError:false,interested:false,news:null,newsError:false,newsLoading:false,commentDraft:{},busy:false};
 let learning={};try{learning=JSON.parse(localStorage.getItem('still-learning')||'{}');if(!learning||typeof learning!=='object'||Array.isArray(learning))learning={};}catch{}
 const txt=key=>esc(t(key)),loc=value=>esc(typeof value==='object'?value[prefs().language]??value.en:value),link=(url,label,cls='resource-link')=>`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}${ico('external')}</a>`;
 const header=(label,title,intro)=>`<header class="community-header"><div class="eyebrow">${txt(label)}</div><h1>${txt(title)}</h1><p>${txt(intro)}</p></header>`;
 async function api(path,body,method=body?'POST':'GET') {const r=await fetch(path,{method,headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})});if(!r.ok||!r.headers.get('content-type')?.includes('application/json'))throw Error('unavailable');return r.json();}
 function saveLearning(){try{localStorage.setItem('still-learning',JSON.stringify(learning));return true;}catch{toast(t('storageError'));return false;}}
 function newsItem(n){return {...n,type:'news',icon:'sun',color:'sand',source:'Positive News · '+new Intl.DateTimeFormat(prefs().language,{dateStyle:'medium',timeStyle:'short'}).format(new Date(n.published)),body:{en:t('newsNote')},resources:[['read','Positive News',n.url]]};}
 function getItem(id){return FEED.find(x=>x.id===id)||s.news?.items.map(newsItem).find(x=>x.id===id);}
 function tags(item){return `<div class="topic-tags">${item.tags.map(k=>item.type==='news'?`<span>${esc(k)}</span>`:`<button data-feed-filter="${k}">${txt(k)}</button>`).join('')}</div>`;}
 function social(item){return `<div class="social-row"><button data-like="${item.id}" aria-pressed="${s.liked.includes(item.id)}" aria-label="${txt(s.liked.includes(item.id)?'liked':'like')}" class="${s.liked.includes(item.id)?'is-liked':''}">${ico('heart')}<span>${s.likes[item.id]||0}</span><span class="social-label">${txt('like')}</span></button><button data-comments="${item.id}">${ico('chat')}<span>${s.counts[item.id]||0}</span><span class="social-label">${txt('comment')}</span></button><button data-share="${item.id}">${ico('share')}<span>${txt('share')}</span></button></div>`;}
 function feedCard(item){return `<article class="feed-card"><div class="feed-byline"><span class="feed-avatar ${item.color}">${ico(item.icon)}</span><div><strong>${esc(item.source)}</strong><span>${txt(item.type)}</span></div></div>${tags(item)}<button class="feed-open" data-story="${item.id}"><h2>${loc(item.title)}</h2><p>${loc(item.summary)}</p><span class="read-prompt">${txt('readMore')}${ico('arrow')}</span></button>${social(item)}</article>`;}
 function newsBlock(){return `<section class="news-section"><div class="section-heading"><h2>${txt('newsIntro')}</h2><button class="icon-button" data-community="refresh-news" aria-label="${txt('retry')}">${ico('refresh')}</button></div><p class="mini-note">${txt('newsNote')}</p>${s.newsLoading?`<p role="status">${txt('loadingFeed')}</p>`:s.newsError?`<p class="empty-inline" role="status">${txt('newsError')}</p>`:!s.news?.items.length?`<p class="empty-inline">${txt('newsEmpty')}</p>`:s.news.items.map(n=>feedCard(newsItem(n))).join('')}${s.news?`<p class="mini-note">${txt('checked')} · ${esc(new Intl.DateTimeFormat(prefs().language,{timeStyle:'short'}).format(new Date(s.news.checkedAt)))}</p>`:''}</section>`;}
 function feedRows(){const items=visibleFeed(prefs().tradition,s.filter==='news'?'all':s.filter,s.query);const moodTag={sad:'sadness',lonely:'loneliness',anxious:'fear',hopeless:'hope',grateful:'grace',hopeful:'hope',overwhelmed:'comfort',peaceful:'peace'}[getMood()];if(moodTag)items.sort((a,b)=>Number(b.tags.includes(moodTag))-Number(a.tags.includes(moodTag)));return `${s.filter==='news'?newsBlock():''}${items.map(feedCard).join('')||`<p class="empty-inline">${txt('noResults')}</p>`}`;}
 function explore(){if(s.item)return detail();return `${header('explore','exploreHeading','exploreIntro')}<div class="feed-search">${ico('search')}<input id="explore-search" type="search" placeholder="${txt('searchExplore')}" aria-label="${txt('searchExplore')}" value="${esc(s.query)}"></div><div class="filter-strip" aria-label="${txt('explore')}">${['all','stories','music','psalms','prayers','bible','news'].map(k=>`<button data-feed-filter="${k}" aria-pressed="${s.filter===k}">${txt(k)}</button>`).join('')}</div>${!['all','stories','music','psalms','prayers','bible','news'].includes(s.filter)?`<button class="active-filter" data-feed-filter="all">${txt(s.filter)} ${ico('close')}</button>`:''}<div id="feed-list">${feedRows()}</div>${helpBanner()}`;}
 function detail(){const item=getItem(s.item);if(!item||(item.tradition&&item.tradition!==prefs().tradition)){s.item=null;return explore();}return `<section class="story-detail"><button class="text-button" data-community="back-explore">${ico('back')}${txt('backExplore')}</button><div class="detail-cover ${item.color}">${ico(item.icon)}<span>${txt(item.type)}</span></div>${tags(item)}<h1>${loc(item.title)}</h1><div class="story-meta">${esc(item.source)}</div><p class="story-lead">${loc(item.summary)}</p><h2>${txt('contextTitle')}</h2><p>${loc(item.body)}</p>${['psalm-23','psalm-23-sung'].includes(item.id)?psalmText():''}${social(item)}${item.resources.length?`<section class="deeper"><h2>${txt('goDeeper')}</h2>${item.resources.map(([type,name,url])=>link(url,`<span class="resource-icon">${ico(type==='listen'?'music':type==='watch'?'play':'book')}</span><span><small>${txt(type)}</small>${esc(name)}</span>`)).join('')}<p class="mini-note">${txt('externalContent')}</p></section>`:''}<section id="conversation" class="conversation"><h2>${txt('commentsTitle')}</h2><p class="mini-note">${txt('commentPrivacy')}</p><div id="comment-list">${commentRows()}</div><form id="comment-form"><label for="comment-name">${txt('displayName')}</label><input id="comment-name" maxlength="40" autocomplete="nickname" required value="${esc(s.commentDraft[item.id]?.name??'')}"><label class="sr-only" for="comment-body">${txt('comment')}</label><textarea id="comment-body" maxlength="600" required placeholder="${txt('commentPlaceholder')}">${esc(s.commentDraft[item.id]?.body??'')}</textarea><div class="comment-submit"><small>600 ${txt('characters')}</small><button class="primary" type="submit">${txt('postComment')}</button></div><p id="comment-error" role="alert"></p></form></section></section>`;}
 function psalmText(){const edition=getEdition(),psalm=PSALM23[edition?.id];if(!psalm)return `<p class="note-box">${txt('unavailable')}<button class="text-button" data-action="settings">${txt('settings')}</button></p>`;return `<details class="psalm-reader"><summary>${ico('book')}${esc(psalm.reference)} · ${txt('read')}</summary><div lang="${esc(edition.language)}"><p class="edition-label">${esc(edition.name)}</p>${psalm.verses.map((verse,i)=>`<p><sup>${i+1}</sup>${esc(verse)}</p>`).join('')}</div>${link(psalm.source,txt('source'))}<p class="mini-note">${esc(edition.attribution)} ${link(edition.licenseUrl,esc(edition.license))}</p></details>`;}
 function commentRows(){if(s.commentsLoading)return `<p role="status">${txt('loadingFeed')}</p>`;if(s.commentsError)return `<p>${txt('socialError')}</p><button class="text-button" data-community="reload-comments">${txt('retry')}</button>`;return s.comments.length?s.comments.map(c=>`<article class="comment-item"><div><strong>${esc(c.name)}</strong><time>${esc(new Intl.DateTimeFormat(prefs().language,{dateStyle:'medium'}).format(new Date(c.created)))}</time></div><p>${esc(c.body)}</p>${c.mine?`<button class="text-button" data-remove-comment="${esc(c.id)}">${txt('removeComment')}</button>`:''}</article>`).join(''):`<p class="empty-inline">${txt('noComments')}</p>`;}
 async function comments(){const id=s.item;if(!id)return;s.commentsLoading=true;s.commentsError=false;s.comments=[];updateCommentRows();try{const data=await api('/api/items/'+id+'/comments');if(s.item===id)s.comments=data.comments;}catch{if(s.item===id)s.commentsError=true;}finally{if(s.item===id){s.commentsLoading=false;updateCommentRows();}}}
 function updateCommentRows(){const el=document.querySelector('#comment-list');if(el)el.innerHTML=commentRows();}
 async function loadNews(){if(s.newsLoading)return;s.newsLoading=true;s.newsError=false;updateFeed();try{s.news=await api('/api/news');}catch{s.newsError=true;}finally{s.newsLoading=false;updateFeed();}}
 function updateFeed(){const el=document.querySelector('#feed-list');if(el)el.innerHTML=feedRows();}
 function courseCard(c){return `<article class="course-card"><button data-course="${c.id}"><div class="course-art ${c.color}">${ico(c.icon)}<span>${txt('free')}</span></div><div class="course-card-copy"><div class="eyebrow">${txt(c.category)}</div><h2>${loc(c.title)}</h2><p>${esc(c.provider)}</p><div class="course-meta">${txt(c.format)}<br>${c.lang==='English'?txt('contentEnglish'):c.lang==='Multiple languages'?txt('contentMultilingual'):esc(c.lang)}</div><span class="read-prompt">${txt('viewCourse')}${ico('arrow')}</span></div></button></article>`;}
 function learn(){if(s.course)return courseDetail();return `${header('learn','learnHeading','learnIntro')}<div class="learning-categories">${CATEGORIES.map(k=>`<button data-category="${k}" aria-pressed="${s.category===k}">${ico({theology:'book',mindfulness:'leaf',breathwork:'breath',journaling:'pen',music:'music',art:'art'}[k])}<span>${txt(k)}</span></button>`).join('')}</div><div class="section-heading"><h2>${txt(s.category==='all'?'allCourses':s.category)}</h2>${s.category!=='all'?`<button class="text-button" data-category="all">${txt('allCourses')}</button>`:''}</div><div class="learning-grid">${COURSES.filter(c=>s.category==='all'||c.category===s.category).map(courseCard).join('')}</div><p class="mini-note course-footer">${txt('courseNote')}</p>`;}
 function courseDetail(){const c=COURSES.find(x=>x.id===s.course);if(!c){s.course=null;return learn();}const done=learning[c.id]?.done||[];return `<section class="course-detail"><button class="text-button" data-community="back-learn">${ico('back')}${txt('backLearn')}</button><div class="detail-cover ${c.color}">${ico(c.icon)}<span>${txt('free')} · ${txt(c.format)}</span></div><div class="eyebrow">${txt(c.category)} · ${c.lang==='English'?txt('contentEnglish'):c.lang==='Multiple languages'?txt('contentMultilingual'):esc(c.lang)}</div><h1>${loc(c.title)}</h1><p class="story-meta">${esc(c.provider)}</p><p class="story-lead">${loc(c.summary)}</p>${c.lessons?`<h2>${txt('lessons')} · ${done.length}/${c.lessons.length}</h2><div class="lesson-list">${c.lessons.map((k,i)=>`<button data-lesson="${i}" aria-pressed="${s.lesson===i}"><span>${done.includes(i)?ico('check'):i+1}</span>${txt(c.category)} · ${i+1}</button>`).join('')}</div><article class="lesson-content"><p>${txt(c.lessons[s.lesson])}</p><button class="secondary" data-community="complete-lesson">${ico(done.includes(s.lesson)?'check':'arrow')}${txt(done.includes(s.lesson)?'lessonComplete':'lessonDone')}</button></article>${c.category==='breathwork'?`<button class="primary full" data-action="breathe">${txt('begin')}${ico('play')}</button>`:c.category==='journaling'?`<button class="primary full" data-action="journal">${txt('journal')}${ico('pen')}</button>`:''}${c.url?link(c.url,txt('source')):''}`:`${link(c.url,txt('startCourse'),'primary full external-course')}<button class="secondary full" data-community="save-course">${ico('bookmark')}${txt(learning[c.id]?.saved?'savedCourse':'saveCourse')}</button>`}<p class="mini-note course-footer">${txt('courseNote')}</p></section>`;}
 function helpBanner(){return `<section class="help-banner"><span class="icon-bubble">${ico('heart')}</span><div><h2>${txt('helpBrazil')}</h2><p>${txt('helpBrazilSub')}</p><button class="text-button" data-nav="kindness">${txt('browseOrganizations')}${ico('arrow')}</button></div></section>`;}
 function organizations(){const profile=getProfile(),matches=organizationsForCity(ORGANIZATIONS,profile),city=profile?.city;return `${header('pNearYou','browseOrganizations','orgIntro')}<section class="location-card"><div class="eyebrow">${txt('pYourCity')}</div>${city?`<strong>${esc(city)} · ${esc(profile.region)}</strong>`:`<p>${txt('pNoCity')}</p>`}<button class="text-button" data-profile="location">${ico('pin')}${txt(city?'pChangeCity':'pSetCity')}</button></section>${city&&!matches.length?`<p class="empty-inline">${txt('pNoOrganizations')}</p>`:''}${matches.map(o=>`<article class="organization-card"><div class="eyebrow">Brasil · ${esc(city)}</div><h2>${esc(o.name)}</h2><p>${txt(o.kind)}</p>${o.headquarters&&profile.region!=='SP'?`<p class="note-box">${txt('pNetworkNote')}</p>`:''}<address>${ico('pin')}<span>${esc(o.address)}</span></address>${o.headquarters?`<p class="mini-note">${txt('headquarters')}</p>`:''}<a href="mailto:${esc(o.email)}">${esc(o.email)}</a>${o.phone?`<a href="tel:${o.phone.replace(/[^+\d]/g,'')}">${esc(o.phone)}</a>`:''}<div class="org-actions">${link(o.volunteer,txt('volunteer'),'primary')}${link(o.contact,txt('contactOrg'),'secondary')}${link(o.donate,txt('donate'),'text-button')}${link('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(o.address),txt('map'),'text-button')}</div><p class="mini-note">${txt('orgNote')}</p></article>`).join('')}${city?`<section class="directory-fallback">${profile.country==='BR'?link('https://www.atados.com.br',txt('pAtados')):''}${link('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent('charities volunteering '+[city,profile.region,profile.country==='OTHER'?'':profile.country].filter(Boolean).join(', ')),txt('pLocalSearch'))}<p class="mini-note">${txt('pDirectoryNote')}</p></section>`:''}${matches.length?`<p class="mini-note">${txt('checkedOrganizations')}</p>`:''}`;}
 function gathers(){const monthDate=new Date(s.year,s.month,1),days=calendarDays(s.year,s.month),today=new Date();today.setHours(0,0,0,0);const chosen=new Date(s.year,s.month,s.day),proposed=chosen.getDay()===4&&chosen>=today;const week=Array.from({length:7},(_,i)=>new Intl.DateTimeFormat(prefs().language,{weekday:'short'}).format(new Date(2026,10,1+i)));return `${header('gather','gatherHeading','gatherIntro')}<section class="calendar"><div class="calendar-top"><button class="icon-button" data-month="-1" aria-label="${txt('previousMonth')}">${ico('back')}</button><h2>${esc(new Intl.DateTimeFormat(prefs().language,{month:'long',year:'numeric'}).format(monthDate))}</h2><button class="icon-button" data-month="1" aria-label="${txt('nextMonth')}">${ico('arrow')}</button></div><div class="calendar-week">${week.map(d=>`<span>${esc(d)}</span>`).join('')}</div><div class="calendar-grid">${'<span></span>'.repeat(monthDate.getDay())}${days.map(d=>{const date=new Date(s.year,s.month,d.day),isProposed=d.proposed&&date>=today;return `<button data-day="${d.day}" class="${isProposed?'proposed':''} ${d.day===s.day?'selected':''} ${date.getTime()===today.getTime()?'today':''}" aria-label="${esc(new Intl.DateTimeFormat(prefs().language,{dateStyle:'full'}).format(date))}${isProposed?' · '+txt('plannedDate'):''}" aria-pressed="${d.day===s.day}">${d.day}<i aria-hidden="true"></i></button>`;}).join('')}</div><p class="calendar-legend"><i></i>${txt('proposedLegend')}</p></section><div class="section-heading"><h2>${esc(new Intl.DateTimeFormat(prefs().language,{weekday:'long',month:'short',day:'numeric'}).format(chosen))}</h2></div>${proposed?`<article class="session-card"><div class="eyebrow">${txt('plannedDate')} · ${txt('weeklySessionTitle')}</div><div class="session-icon">${ico('people')}</div><h2>${txt('sessionTopic')}</h2><p>${txt('sessionDescription')}</p><p class="session-pending">${ico('clock')}${txt('sessionPending')}</p><button class="primary full" data-community="interest" aria-pressed="${s.interested}">${ico(s.interested?'check':'heart')}${txt(s.interested?'interestSaved':'interested')}</button><p class="mini-note">${txt('interestNote')}</p><p class="mini-note">${txt('groupBoundary')}</p></article>`:`<p class="empty-inline">${txt('noSession')}</p>`}${helpBanner()}`;}
 function evidence(id,passage){const e=EVIDENCE[ACTION_EVIDENCE[id]];if(!e)return '';return `<details class="evidence"><summary>${ico('book')}${txt('whyHelp')}</summary><div class="evidence-body"><div class="eyebrow">${txt(e.spiritual?'spiritualBasis':'evidenceBasis')}</div><p>${txt(e.key)}</p>${e.url?link(e.url,esc(e.source)):''}${passage?`<div class="eyebrow">${txt('scriptureBasis')}</div><p>${esc(passage.context?.[prefs().language]||passage.reference)}</p>${link(passage.sourceUrl,esc(passage.reference)+' · '+esc(passage.editionName))}`:''}<small>${txt('evidenceNote')}</small></div></details>`;}
 async function ready(){try{const data=await api('/api/social');s.liked=data.liked;s.likes=Object.fromEntries(data.likes.map(x=>[x.item,x.count]));s.counts=Object.fromEntries(data.comments.map(x=>[x.item,x.count]));s.interested=data.interested;refreshSocial();}catch{/* No optimistic counts or fake success when the service is unavailable. */}}
 function refreshSocial(){document.querySelectorAll('[data-like]').forEach(b=>{const id=b.dataset.like,liked=s.liked.includes(id);b.setAttribute('aria-pressed',String(liked));b.setAttribute('aria-label',t(liked?'liked':'like'));b.classList.toggle('is-liked',liked);b.querySelector('span').textContent=s.likes[id]||0;});document.querySelectorAll('[data-comments]').forEach(b=>b.querySelector('span').textContent=s.counts[b.dataset.comments]||0);const interest=document.querySelector('[data-community="interest"]');if(interest){interest.setAttribute('aria-pressed',String(s.interested));interest.innerHTML=ico(s.interested?'check':'heart')+txt(s.interested?'interestSaved':'interested');}}
 function route(){const h=location.hash.slice(1).split('/');if(h[0]==='explore'&&h[1]?.startsWith('news-')){s.item=null;s.filter='news';navigate('explore');loadNews();return true;}if(h[0]==='explore'&&h[1]&&FEED.some(x=>x.id===h[1])){s.item=h[1];navigate('explore');comments();return true;}if(['explore','learn','gather'].includes(h[0])){s.item=null;s.course=null;navigate(h[0]);return true;}return false;}
 function reset(page){if(page==='explore'){s.item=null;history.replaceState(null,'',location.pathname+'#explore');}if(page==='learn')s.course=null;}
 async function handleClick(el){
  if(el.dataset.story){if(el.dataset.story.startsWith('news-')){s.item=el.dataset.story;navigate('explore');comments();}else location.hash='explore/'+el.dataset.story;return true;}
  if(el.dataset.feedFilter){s.filter=el.dataset.feedFilter;s.item=null;navigate('explore');history.replaceState(null,'',location.pathname+'#explore');if(s.filter==='news')loadNews();return true;}
  if(el.dataset.like){el.disabled=true;const id=el.dataset.like;try{const data=await api('/api/items/'+id+'/like',{liked:!s.liked.includes(id)});s.liked=s.liked.filter(x=>x!==id);if(data.liked)s.liked.push(id);s.likes[id]=data.count;refreshSocial();}catch{toast(t('socialError'));}finally{el.disabled=false;}return true;}
  if(el.dataset.comments){if(s.item!==el.dataset.comments){s.item=el.dataset.comments;history.replaceState(null,'',location.pathname+'#explore/'+s.item);navigate('explore');comments();}document.querySelector('#conversation')?.scrollIntoView({behavior:'smooth'});return true;}
  if(el.dataset.share){const item=getItem(el.dataset.share),url=item.type==='news'?item.url:new URL('#explore/'+item.id,location.href).href;try{if(navigator.share)await navigator.share({title:typeof item.title==='string'?item.title:item.title[prefs().language],url});else{await navigator.clipboard.writeText(url);toast(t('linkCopied'));}}catch(e){if(e.name!=='AbortError')modal('share',`<label for="share-url">${txt('shareLink')}</label><input id="share-url" readonly value="${esc(url)}">`);}return true;}
  if(el.dataset.removeComment){el.disabled=true;try{await api('/api/items/'+s.item+'/comments/'+el.dataset.removeComment,{},'DELETE');s.comments=s.comments.filter(x=>x.id!==el.dataset.removeComment);s.counts[s.item]=Math.max(0,(s.counts[s.item]||0)-1);updateCommentRows();refreshSocial();}catch{toast(t('socialError'));el.disabled=false;}return true;}
  if(el.dataset.category){s.category=el.dataset.category;render();return true;}
  if(el.dataset.course){s.course=el.dataset.course;s.lesson=0;render();focusMain();return true;}
  if(el.dataset.lesson!==undefined){s.lesson=Number(el.dataset.lesson);render();return true;}
  if(el.dataset.month){const d=new Date(s.year,s.month+Number(el.dataset.month),1);s.year=d.getFullYear();s.month=d.getMonth();s.day=1;render();return true;}
  if(el.dataset.day){s.day=Number(el.dataset.day);render();return true;}
  const action=el.dataset.community;if(!action)return false;
  if(action==='back-explore'){s.item=null;history.replaceState(null,'',location.pathname+'#explore');render();focusMain();}
  if(action==='back-learn'){s.course=null;render();focusMain();}
  if(action==='reload-comments')comments();if(action==='refresh-news')loadNews();
  if(action==='complete-lesson'){const old=learning[s.course];learning[s.course]={...old,done:[...new Set([...(old?.done||[]),s.lesson])]};if(!saveLearning())learning[s.course]=old;render();}
  if(action==='save-course'){const old=learning[s.course];learning[s.course]={...old,saved:!old?.saved};if(!saveLearning())learning[s.course]=old;render();}
  if(action==='interest'){el.disabled=true;try{s.interested=(await api('/api/interest',{interested:!s.interested})).interested;refreshSocial();}catch{toast(t('socialError'));}finally{el.disabled=false;}}
  return true;
 }
 function handleInput(el){if(el.id==='explore-search'){s.query=el.value;updateFeed();}if(['comment-body','comment-name'].includes(el.id)&&s.item)s.commentDraft[s.item]={name:document.querySelector('#comment-name').value,body:document.querySelector('#comment-body').value};}
 async function submit(event){if(event.target.id!=='comment-form')return;event.preventDefault();if(s.busy)return;const item=s.item,name=document.querySelector('#comment-name').value.trim(),body=document.querySelector('#comment-body').value.trim(),err=document.querySelector('#comment-error'),btn=event.target.querySelector('button');if(!name||!body||body.length>600){err.textContent=t('invalidComment');return;}s.busy=true;btn.disabled=true;err.textContent='';try{const data=await api('/api/items/'+item+'/comments',{name,body});s.commentDraft[item]={name,body:''};if(s.item===item){s.commentsError=false;s.comments.unshift(data.comment);s.counts[item]=(s.counts[item]||0)+1;document.querySelector('#comment-body').value='';updateCommentRows();refreshSocial();}}catch{err.textContent=t('socialError');}finally{s.busy=false;btn.disabled=false;}}
 const days=calendarDays(s.year,s.month);s.day=days.find(d=>d.day>=now.getDate()&&d.proposed)?.day??now.getDate();
 window.addEventListener('hashchange',route);document.addEventListener('submit',submit);
 return {explore,learn,gathers,organizations,evidence,ready,route,reset,handleClick,handleInput};
}
